from pathlib import Path
import pandas as pd,numpy as np,json,hashlib
H=Path(__file__).resolve().parent;P=H.parents[2].parent
old=pd.read_csv(P/'sofa_extract.csv').set_index('stay_id')
f=H/'data/mimic_sofa_strict48.csv';new=pd.read_csv(f).set_index('stay_id')
cs=['respiration','coagulation','liver','cardiovascular','cns','renal']
checks={'rows_24894':len(new)==24894,'unique_ids':new.index.is_unique,'same_frozen_cohort':set(new.index)==set(old.index),'sum_components_equals_total':bool((new[cs].sum(axis=1)==new.sofa_max_48h).all()),'component_range_0_4':bool(new[cs].notna().all().all() and new[cs].ge(0).all().all() and new[cs].le(4).all().all()),'total_range_0_24':bool(new.sofa_max_48h.between(0,24).all()),'no_source_window_violation':bool((new[[c for c in new.columns if c.endswith('outside_n')]]==0).all().all())}
assert all(checks.values()),checks
old=old.loc[new.index];d=new.sofa_max_48h-old.sofa_max_48h
summary={'checks':checks,'new_csv_sha256':hashlib.sha256(f.read_bytes()).hexdigest(),'n':len(new),'changed_total_n':int((d!=0).sum()),'increased_total_n':int((d>0).sum()),'decreased_total_n':int((d<0).sum()),'delta_new_minus_old_distribution':{str(k):int(v) for k,v in d.value_counts().sort_index().items()},'new_total_summary':new.sofa_max_48h.describe().to_dict(),'component_change_n':{c:int((old[c]!=new[c]).sum()) for c in cs},'component_missing_n':{c:int((new[c+'_hours']==0).sum()) for c in cs},'component_new_distributions':{c:{str(k):int(v) for k,v in new[c].value_counts().sort_index().items()} for c in cs},'uo':{'records_with_eligible_uo':int((new.eligible_uo_endpoints>0).sum()),'high_renal_uo_only_n':int(new.high_renal_uo_only.sum()),'eligible_endpoint_sum':int(new.eligible_uo_endpoints.sum()),'with_min_one_measured_interval_n':int((new.uo_min_interval_count==1).sum()),'max_gap_hours_summary':new.uo_max_gap_h.describe().to_dict(),'high_renal_uo_only_maxgap_hours_summary':new.loc[new.high_renal_uo_only==1,'uo_max_gap_h'].describe().to_dict(),'caution':'max_gap and min_interval_count are over all eligible endpoints in a stay, not necessarily the endpoint determining renal score; irregular interval coverage is not verified continuous monitoring.'},'gcs':{c:int(new[c].sum()) for c in new.columns if c.startswith('n_gcs_')}}
(H/'strict48_score_qa.json').write_text(json.dumps(summary,indent=2,ensure_ascii=False));print(json.dumps(summary,indent=2,ensure_ascii=False))
